-- ============================================================
-- मौजूदा (पहले से कोड में hardcoded) थाना/ज़िला अंग्रेज़ी-अनुवाद डेटा में भरना
--
-- यह एक बार चलने वाली backfill स्क्रिप्ट है — पहले से मौजूद अनुवाद (1665 जोड़े,
-- जो पहले सिर्फ़ mobile app के कोड में थे) को अब असली police_stations तालिका में
-- भर देती है, ताकि पुराना डेटा तुरंत काम आए। सिर्फ़ खाली (station_en/district_en
-- अभी तक NULL) पंक्तियों पर असर पड़ता है — पहले से भरा कुछ नहीं बदलता।
-- जिन entries का district/station से मेल न मिले, वे बस चुपचाप छूट जाती हैं
-- (कोई त्रुटि नहीं आती)।
--
-- चलाने के लिए:
--   psql "$DATABASE_URL" -f src/db/backfill_station_english_names.sql
-- ============================================================

-- 🛡️ सुरक्षा-जाल: यह फ़ाइल station_en/district_en कॉलम पर काम करती है पर उन्हें बनाती
-- नहीं। चूंकि ये migration फ़ाइलें हाथ से एक-एक करके चलाई जाती हैं, क्रम गड़बड़ाने पर
-- "column does not exist" आ जाता। इसलिए यहीं सुनिश्चित कर लेते हैं (पहले से हों तो
-- कुछ नहीं होता)।
ALTER TABLE police_stations ADD COLUMN IF NOT EXISTS district_en TEXT;
ALTER TABLE police_stations ADD COLUMN IF NOT EXISTS station_en  TEXT;

